import java.lang.management.BufferPoolMXBean;
import java.lang.management.ManagementFactory;

public class OffHeapMetrics {
    public static void logDirectMemory() {
        for (BufferPoolMXBean pool : ManagementFactory.getPlatformMXBeans(BufferPoolMXBean.class)) {
            System.out.printf("pool=%s count=%d usedMiB=%.2f capacityMiB=%.2f%n",
                pool.getName(), pool.getCount(),
                pool.getMemoryUsed() / (1024.0 * 1024.0),
                pool.getTotalCapacity() / (1024.0 * 1024.0));
        }
    }
}

